local sb,sc=string.byte,string.char
local function DEC(h,k)
local n=#h
local m={}
local i=1
while i<n do
local hi=sb(h,i)
local lo=sb(h,i+1)
hi=(hi>=97) and (hi-87) or ((hi>=65) and (hi-55) or (hi-48))
lo=(lo>=97) and (lo-87) or ((lo>=65) and (lo-55) or (lo-48))
local v=hi*16+lo
local kk=k[((i-1)/2)%#k+1]
local r,p=0,1
local x,y=v,kk
while x>0 or y>0 do
local xa,ya=x%2,y%2
if xa~=ya then r=r+p end
x=(x-xa)/2 y=(y-ya)/2 p=p*2
end
m[#m+1]=sc(r)
i=i+2
end
return table.concat(m)
end
local L1=DEC(HX,KY)
local function DEC2(s,k)
local o={}
for i=1,#s do
local b=sb(s,i)
local kk=k[(i-1)%#k+1]
local mix=((i-1)*31)%256
local r,q=0,1
local x,y=b,kk
while x>0 or y>0 do
local xa,ya=x%2,y%2
if xa~=ya then r=r+q end
x=(x-xa)/2 y=(y-ya)/2 q=q*2
end
local r2,q2=0,1
local x2,y2=r,mix
while x2>0 or y2>0 do
local xa,ya=x2%2,y2%2
if xa~=ya then r2=r2+q2 end
x2=(x2-xa)/2 y2=(y2-ya)/2 q2=q2*2
end
o[#o+1]=sc(r2)
end
return table.concat(o)
end
local P=DEC2(L1,K2)
local F, OM
do
local fn=loadstring(P)
if not fn then return end
F, OM = fn()
end
local function DECSTR(F,sk)
for _,p in pairs(F) do
local k=p.k
for i=1,#k do
local v=k[i]
if type(v)=='string' then
local o={}
for j=1,#v do
local b=sb(v,j)
local kk=sk[(j-1)%#sk+1]
local r,q=0,1
local x,y=b,kk
while x>0 or y>0 do
local xa,ya=x%2,y%2
if xa~=ya then r=r+q end
x=(x-xa)/2 y=(y-ya)/2 q=q*2
end
o[#o+1]=sc(r)
end
k[i]=table.concat(o)
end
end
end
end
